INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('B02-AS04','study','Allocate Optima 英国G-Cloud14 料金・契約仕様','B02資料確認','supplier_procurement_declaration','{"product_id":"US11","study_design":"supplier_procurement_declaration","document_date":"2024-05-07","independent_efficacy_evidence":false}','料金帯・小規模枠の除外機能をPDF画像で確認。現在の一般販売料金や独立した性能証明ではない。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('CASE01','study','那覇市立病院 / JP01',NULL,'vendor_case_not_independently_tested','{"case_id": "CASE01", "limitations": "導入時に希望休回数ルールも変更。システム単独の因果効果は分離できない。見出し8割と本文の概数が異なるため本文を採用。", "organization": "那覇市立病院", "pid": "JP01", "result": "8時間程度→約2時間（担当者コメント）", "scope": "対象の部署人数・期間は未公表", "sid": "W026"}','導入時に希望休回数ルールも変更。システム単独の因果効果は分離できない。見出し8割と本文の概数が異なるため本文を採用。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('CASE02','study','特養パール代官山 / JP07',NULL,'vendor_case_not_independently_tested','{"case_id": "CASE02", "limitations": "実時間の前後値・独立計測なし。採用成果は他施策の影響を分離できない。", "organization": "特養パール代官山", "pid": "JP07", "result": "作成時間が半分以下、シフト作成残業ほぼゼロとのコメント", "scope": "職員33人・入居50名＋短期10床、2026年7月公開、導入約1年", "sid": "W027"}','実時間の前後値・独立計測なし。採用成果は他施策の影響を分離できない。');
