INSERT INTO "criteria" ("criterion_id","field_key","domain_id","label_ja","definition","data_type","research_stage","applicability","required_evidence","design_reference_urls_json","schema_version") VALUES ('P04','setup_cost','P','導入初期費用','必須・任意の設定、移行、研修、個別開発を項目別に記録する。不明はnull。','record','L1_common','商用製品・有償エンジン','公式料金・個別見積・契約書','["https://www.otasukeman.jp/price"]','2.0');
