INSERT INTO "criteria" ("criterion_id","field_key","domain_id","label_ja","definition","data_type","research_stage","applicability","required_evidence","design_reference_urls_json","schema_version") VALUES ('Q07','adoption_retention_evidence','Q','導入数・継続の実績','法人・施設・ユーザーの単位、集計日、有償本番の別を明記し、累計登録と混同しない。','record','L2_deep','商用製品・導入事例','利用施設の一次発信・導入事例・許可された聞き取り','["https://nursing.jmir.org/2026/1/e94450"]','2.0');
