INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B15-20261012','document_observation','B15-20261012-OBS0053','OF-JP24','M04','known','{"summary_ja":"solveの402応答仕様にはAPIキー、x402、mppの支払い認証候補を定義する。環境によりx402未設定・検証失敗時の応答も定義する。"}','limited','addon','documented','source_statement','{"record_category":"document_observation","research_batch":"B15-20261012","scope":"通常Web版と区別した公開Solver API・MCPベータ。Web版の有料プロとAPI pro tierは別。"}','仕様上の選択肢で、全経路の現在の提供・単価・決済成立を保証しない。決済・接続・API呼出しは未実施。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B16-20261012','document_observation','B16-20261012-OBS0001','OF-US03','B05','known','{"summary_ja":"セルフスケジューリングに加え周期型スケジューリングを掲載し、労働組合のある環境とない環境の両方を対象に挙げる。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B16-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','職員による枠選択・周期型勤務の公開案内。全自動割当、組合規則の具体的設定・強制力、例外承認、対象契約は未確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B16-20261012','document_observation','B16-20261012-OBS0002','OF-US03','B01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B16-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','この公開ページの確認範囲。非対応とは判断しない。予測人数、募集の自動化、固定周期の設定だけで勤務表最適化を確認済みにしない。','需要予測・空き枠募集・セルフ／周期型勤務は記載されるが、職員を希望・必要人数・制約から全自動割当する詳細手順は今回本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B16-20261012','document_observation','B16-20261012-OBS0003','OF-US03','B07','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B16-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','同一ページへの掲載を同一契約への内包と解釈しない。現行の注文書・製品別契約資料は未取得。','機能群を紹介するが、機能別の標準内包・追加契約・エディション条件を分けた表は今回本文に見つからない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B16-20261012','document_observation','B16-20261012-OBS0004','OF-US03','E03','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B16-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','fairnessという説明だけでFTE補正を確認済みにしない。顧客事例のFTE未勤務時間の監視も公平な割当の算式とは別。','公平性に言及するが、契約勤務量や勤務可能枠に応じた配分補正の算式・設定は今回本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B16-20261012','document_observation','B16-20261012-OBS0005','OF-US03','P01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B16-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','非公開範囲の確認。問い合わせ導線だけで個別見積もり方式を確定せず、0円や料金明細を追加しない。','デモ依頼導線はあるが、製品の価格表・金額・課金単位・最低契約は今回本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
