INSERT INTO "observations" ("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES ('B06-20261011','document_observation','B06-20261011-CORR002','OF-JP04','M02','known','{"summary_ja":"勤務表はExcel・CSV・PDF出力。ただし全設定・監査履歴の一括搬出は確認できない。"}','limited','unknown','documented','source_statement','{"rationale":"通常の勤務表出力であり、設定・履歴を含む解約全量出力の確認ではない。","record_category":"document_observation","research_batch":"B06-20261011","review_method":"editorial_reclassification"}','提供元の機能案内の確認。計算結果・届出の適合・契約適用・実動作は未検証。',NULL,NULL,NULL,'2026-10-11','Aqsh調査支援 / 公開一次資料レビュー','B03-20261011-OBS0223');
