INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ADMIN-ASSISTANT','事務的看護補助者の数と上限','reimbursement_rule','JP','{"eligibility":{"administrative_duty_fraction":0.5,"operator":">="},"formula":"F/(days*8)","limit_formula":"(A/200)*3","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3⑩／p.3 ※3","metric":"administrative_nursing_assistants","rounding":"この様式では明記なし","schema_version":1,"summary_ja":"事務業務が延べ時間の5割以上の職員を区分。実績F/(日数×8)、上限(A/200)×3。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ASSISTANT-NIGHT','夜間看護補助者の必要数','reimbursement_rule','JP','{"formula":"A/staffing_ratio","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3⑨参考","metric":"required_night_assistants","rounding_reference_id":"REG-JP-R8-ROUND-REQUIRED","schema_version":1,"summary_ja":"夜間の必要数はA／配置区分の数。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ATTACHMENTS','様式9に添付する実績と夜間配置','reimbursement_rule','JP','{"conditions":"対象入院料・加算ごとに様式9の2等を確認","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.4 届出上の注意1・2・5","metric":"filing_attachments","schema_version":1,"summary_ja":"直前1か月の実績と勤務体制・申し送りを添付。対象夜間加算は日別患者数・配置を示す資料も必要。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-EMERGENCY','例外的な短時間対応の算入','reimbursement_rule','JP','{"conditions":["院内緊急対応等・日常診療の延長・短時間","当該病棟入院患者への一時的な病棟外看護","状態変化への短時間対応は30分程度と例示"],"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.15 施設基準キ・ク／別紙5抜粋","metric":"exceptional_off_ward_hours_inclusion","schema_version":1,"summary_ja":"院内緊急時の他患者対応、入院患者の病棟外付き添い、状態変化への短時間対応を条件付きで算入可能。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV002');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-EXTRA-REQUIRED','最小必要数以上の看護職員必要数','reimbursement_rule','JP','{"formula":"(A/50)*3","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3⑦参考","metric":"required_extra_nurses","rounding":"この様式では明記なし","schema_version":1,"summary_ja":"追加の必要配置数はA／50×3。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-FOUR-WEEK','手引き：4週間と暦月の区別','professional_guideline','JP','{"allowed_night_periods":["calendar_month","28_contiguous_days"],"authority_note":"専門団体手引き。行政通知による最終照合は別途必要。","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.7","metric":"night_average_period_choice","schema_version":1,"staffing_period":"calendar_month","summary_ja":"4週間を用いるのは月平均夜勤時間のみ。配置数は暦月で、両実績表と空白のない連続期間を要する。","vendor_implementation_verified":false,"verification_stage":"documented"}','2026診療報酬改定対応版',NULL,NULL,'B06-20261011-REV032');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-MULTI-PROFESSIONAL','多職種協働の必要配置数','reimbursement_rule','JP','{"formulas":{"general":"((A/10)+(A/25))*3","psychiatric":"(A/staffing_ratio)*3"},"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3⑪-⑫","metric":"required_multi_professional_staffing","rounding":"この様式では明記なし","schema_version":1,"summary_ja":"精神科対象は(A/配置区分)×3、一般対象は{A/10+A/25}×3。職種・対象加算を分ける。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-NIGHT-COUNT','夜勤従事者数の兼務按分','reimbursement_rule','JP','{"formula":"ward_night_hours / total_night_hours","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.3 ※4-5","metric":"eligible_night_staff_count","schema_version":1,"summary_ja":"対象の交代制勤務者は通常1。病棟外兼務は当該病棟の夜勤時間／総夜勤時間で計上する。","total_night_hours_includes":"病棟と病棟以外","vendor_implementation_verified":false,"verification_stage":"documented","zero_division_policy":"未確認"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-NIGHT-EXCLUSION','夜勤平均の除外条件と境界','reimbursement_rule','JP','{"boundary":"閾値ちょうどは時間未満の除外に該当しない","conditions":[{"employment":"短時間正職員以外","operator":"<","threshold_hours":16,"ward_scope":"急性期病院一般・急性期一般・7対1・10対1"},{"employment":"短時間正職員","operator":"<","threshold_hours":12,"ward_scope":"同上"},{"operator":"<","threshold_hours":8,"ward_scope":"それ以外"}],"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"pp.3-4 ※4・7","metric":"night_average_exclusions","night_exclusive_staff":"excluded","schema_version":1,"summary_ja":"夜勤専従者、所定時間未満の者をBと夜勤時間の平均から除外する。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-NIGHT-MEAN','様式9 月平均夜勤時間','reimbursement_rule','JP','{"formula":"(D-E)/B","inputs":{"B":"対象夜勤従事職員数（兼務按分後）","D":"当該病棟の月延べ夜勤時間","E":"算定から除外する職員の夜勤時間"},"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3⑥","metric":"monthly_mean_night_hours","rounding":"この様式では明記なし","schema_version":1,"summary_ja":"月平均夜勤時間は(D-E)/B。","vendor_implementation_verified":false,"verification_stage":"documented","zero_division_policy":"未確認"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ROUND-PATIENT','令和8年度 患者数の端数処理','reimbursement_rule','JP','{"example":{"input":"12.34","output":"12.4"},"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.15 改定後","metric":"daily_mean_patients_rounding","rounding":{"decimal_places":1,"mode":"ceiling"},"schema_version":1,"summary_ja":"Aは小数第1位まで切り上げ。12.34→12.4。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV002');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ROUND-REQUIRED','令和8年度 必要数の端数処理','reimbursement_rule','JP','{"applies_to":["required_daily_nurse_staffing","required_night_assistants"],"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.15 改定後","metric":"required_staffing_rounding","rounding":{"decimal_places":1,"mode":"ceiling"},"schema_version":1,"summary_ja":"1日看護職員必要数・夜間看護補助者必要数を小数第1位まで切り上げ。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV002');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-ROUND-STAFF','令和8年度 実績配置数の端数処理','reimbursement_rule','JP','{"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.15 改定後","metric":"daily_mean_nurse_staffing_rounding","rounding":{"decimal_places":1,"mode":"truncate"},"schema_version":1,"summary_ja":"月平均配置数は小数第2位以下切捨て。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV002');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-SHIFT-GRID','勤務実績の三段と集計値','reimbursement_rule','JP','{"formula":"C=sum(ward_day_hours+ward_night_hours); D=sum(ward_night_hours)","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"pp.3-4 ※6","metric":"working_hours_grid","row_roles":["ward_day_hours","ward_night_hours","total_night_hours"],"schema_version":1,"summary_ja":"上段は病棟日勤、中段は病棟夜勤、下段は病棟外を含む総夜勤。Cは上段＋中段、Dは中段。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-STAFF-ACTUAL','月平均1日看護職員配置数','reimbursement_rule','JP','{"formula":"C/(days*8)","limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3②","metric":"daily_mean_nurse_staffing","rounding_reference_id":"REG-JP-R8-ROUND-STAFF","schema_version":1,"summary_ja":"月延べ勤務時間Cを日数×8で除す。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-STAFF-REQUIRED','1日看護職員の必要配置数','reimbursement_rule','JP','{"formula":"(A/staffing_ratio)*3","inputs":{"A":"1日平均入院患者数","staffing_ratio":"届出区分の配置比の数"},"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.2 §3②参考","metric":"required_daily_nurse_staffing","rounding_reference_id":"REG-JP-R8-ROUND-REQUIRED","schema_version":1,"summary_ja":"必要配置数は患者数A／配置区分の数×3。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV001');
INSERT INTO "regulations" ("regulation_id","title","authority_type","jurisdiction","applicability_json","version_label","effective_from","effective_to","revision_id") VALUES ('REG-JP-R8-TRAINING','病棟勤務に算入できる院内研修','reimbursement_rule','JP','{"conditions":["施設が業務の質向上のため受講を指示","保険医療機関内","当該病棟のオンライン／病棟外の集合研修を含む"],"limitations":"資料の参照情報。正式通知・届出区分と施設条件の照合が必要。計算エンジン／制度適合の認定ではない。","locator":"p.15 別紙5抜粋","metric":"training_hours_inclusion","monthly_cap_hours_per_staff":1,"schema_version":1,"summary_ja":"施設が指示した院内研修は、主に当該病棟に従事する職員1名につき月1時間まで算入可能。","vendor_implementation_verified":false,"verification_stage":"documented"}','令和8年度',NULL,NULL,'B06-20261011-REV002');
