INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0013','B03-20261011-REV002','B03-20261011-EV0013','対応制約・cross_shift_demands',NULL,'複数シフトを横断する合計人数条件を指定できる。休憩中の人数保証とは別確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0014','B03-20261011-REV002','B03-20261011-EV0014','対応制約・fairness_groups',NULL,'最大4つの負担配分グループを独立に指定でき、均等化の重みを調整できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0015','B03-20261011-REV002','B03-20261011-EV0015','対応制約・available_weekdays',NULL,'曜日別勤務可否と担当可能シフトを必須条件にできる。日跨ぎは勤務開始日の曜日で判定する。','supports','official_page_body_review','2026-10-11');
