INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0028','B03-20261011-REV003','B03-20261011-EV0028','共有・管理',NULL,'確定勤務の閲覧範囲制限、管理者権限、組織管理を掲載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0029','B03-20261011-REV003','B03-20261011-EV0029','複数拠点管理',NULL,'複数拠点の集約と店舗間応援を掲載。同時最適化や兼務の重複防止は未確定。','supports','official_page_body_review','2026-10-11');
