INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0321','B04-20261011-REV036','B04-20261011-EV0321','第27条',NULL,'必要な情報は契約終了前にダウンロードすること、終了後の提供はしない旨を規定。設定・履歴を含む全量出口を保証する記述ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0322','B04-20261011-REV036','B04-20261011-EV0322','第27条',NULL,'6か月の未使用等でデータを削除することがあり、削除後は復旧できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0323','B04-20261011-REV036','B04-20261011-EV0323','第11条',NULL,'API利用は提供者の許可と限定的な権利に基づく。連携の正確性・即時性を保証せず、終了後は接続できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0324','B04-20261011-REV036','B04-20261011-EV0324','第10条',NULL,'ソフトウェア等の権利は提供者に帰属し、書面許諾なしの改変・逆解析等を禁じる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0325','B04-20261011-REV036','B04-20261011-EV0325','第23条',NULL,'通常のサービス終了は3か月前の告知を規定。やむを得ない場合の例外があり継続保証ではない。','supports','official_page_body_review','2026-10-11');
