INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0329','B04-20261011-REV037','B04-20261011-EV0329','連携表',NULL,'HRMOS、Touch On Time、KING OF TIME、勤革時、Xronos Performance等から実績をCSVで取り込む構成を掲載。','supports','official_page_body_review','2026-10-11');
