INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0332','B04-20261011-REV037','B04-20261011-EV0332','連携設定',NULL,'勤怠から勤務実績を取り込み常勤換算表へ反映する。API自動同期とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0333','B04-20261011-REV037','B04-20261011-EV0333','KING OF TIME設定',NULL,'KING OF TIMEへの夜勤出力は、連続1勤務と夜勤・明けの別勤務の設定を選ぶ。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0334','B04-20261011-REV038','B04-20261011-EV0334','p2 §2 / §9',NULL,'利用規約上の例外を除き24時間365日利用。年間48時間以上の停止を避ける、稼働率99.45%を努力目標として記載。達成保証・返金条項は確認していない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0335','B04-20261011-REV038','B04-20261011-EV0335','p2 §4 / §9',NULL,'有人の操作サポートは平日10〜18時、土日祝・お盆・年末年始を除く。問い合わせ回答を4営業日以上待たせない努力目標。ホームページの相談時間とは対象を分ける。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0336','B04-20261011-REV038','B04-20261011-EV0336','p2 §7',NULL,'24時間ごとにフルバックアップし3世代（72時間前）まで保持。契約者にもバックアップ責任がある。','supports','official_page_body_review','2026-10-11');
