INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0025','B05-20261011-REV004','B05-20261011-EV0025','Risks of setting availability as a hard constraint',NULL,'勤務可能時間とシフトが一部でも合わない場合、必須扱いでは未割当のまま残る。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0026','B05-20261011-REV004','B05-20261011-EV0026','Availability is considered a preferential requirement',NULL,'勤務可否を希望扱いにするには、重要度の見積・設定をQuinyxへ依頼する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0027','B05-20261011-REV004','B05-20261011-EV0027','FAQ: availability as well as an absence',NULL,'同日に勤務可能と欠勤の両方が登録されても欠勤を優先し、自動配置しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0028','B05-20261011-REV004','B05-20261011-EV0028','FAQ: works across multiple units / sections',NULL,'勤務可否はユニット別・セクション別には扱われず、申告先の拠点に限定して割り当てる機能とは異なる。','supports','official_page_body_review','2026-10-11');
