INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B19-20261012-OBS0003','B19-20261012-REV002','B19-20261012-EV0003','アプリ名直下のFree表示 / Developer：SmartLinx Solutions LLC',NULL,'米国App StoreはSmartLinx GoをFreeと表示するが、これはストアのアプリ取得表示であり、法人向けSmartlinx Schedulingの無料プラン・基本料・利用料金を確定する資料ではない。','context','official_page_body_review','2026-10-12');
